function relevantProfile(id,r){const list=areaProfiles(id);const key=r.split('/').pop();const hint=routeHints[key]||key;const terms=hint.toLowerCase().split(/[\s-]+/).filter(x=>x.length>3);return [...list].sort((a,b)=>terms.reduce((n,w)=>n+(b.title.toLowerCase().includes(w)?1:0)-(a.title.toLowerCase().includes(w)?1:0),0))[0]||null}
function matchArea(r){const exact=COVERAGE.areas.find(a=>a.proposed_routes.includes(r));if(exact)return exact;const matched=COVERAGE.areas.flatMap(a=>a.proposed_routes.filter(x=>x.startsWith('/')&&x.includes(':')).map(x=>({a,x}))).filter(({x})=>new RegExp('^'+x.replace(/:[^/]+/g,'[^/]+')+'$').test(r)).sort((a,b)=>b.x.length-a.x.length)[0];return matched?.a||null}
function routeLinksFor(a){return a.proposed_routes.filter(r=>r.startsWith('/')&&!r.includes(':')).map(r=>[r,routeName(r)]).slice(0,14)}
function workflowBrief(p){if(!p)return '';return `<div class="sub-page"><span class="eyebrow">${p.id} · ${t('Fachlicher Sollablauf','Specified workflow')}</span><h3>${esc(p.title)}</h3><p>${esc(p.required_interactions[0]?.action||'')}</p><div class="pill-list">${p.roles.map(x=>`<span class="status">${esc(x.role)}</span>`).join('')}</div><div class="actions">${link(t('Ablauf mit Entscheidungen öffnen','Open flow and decisions'),'/workflow/'+p.id)}${vbtn(t('Ausnahmefall ansehen','View exception path'),'profile-exception',p.id)}</div></div>`}
