function lmsView(r){const course=r.includes('/course/');return `<div class="info-grid">${panel(course?t('Lernraum L-01 · Mathematik','Learning room L-01 · Mathematics'):t('OpenOLAT · Zugang im Blick','OpenOLAT · access overview'),`<p>${t('Die operative Lernstrecke ist OpenOLAT. Hier wird nur eine Integrationsansicht gezeigt; kein SSO-Token oder echter Lernzugang wird erzeugt.','The operational learning pathway is OpenOLAT. This is an integration preview only; no SSO token or real access is created.')}</p><div class="task-row"><strong>${t('Kurszuordnung','Course assignment')}</strong>${badge(t('Muster vorhanden','Sample available'),'blue')}</div><div class="task-row"><strong>${t('Zugangsfreigabe','Access approval')}</strong>${badge(t('Gesondert zu bestätigen','Separate confirmation needed'))}</div>${link(t('Musterkurs öffnen','Open sample course'),'/portal/learning/course/L-01','secondary')}`)}${panel(course?t('Übung & Abgabe','Exercise & submission'):t('Synchronisation & Versionen','Synchronisation & versions'),course?`<p>${t('Musteraufgabe: Beschreibe eine lineare Funktion und notiere einen Anwendungsfall. Nur fiktive Lerninhalte.','Sample task: describe a linear function and give an example use. Fictional learning content only.')}</p>${vbtn(t('Musterabgabe simulieren','Simulate sample submission'),'scenario','learning-submit','')}${V2.pageResults['learning-submit']?notice(t('Musterabgabe lokal markiert. Nicht an OpenOLAT übertragen.','Sample submission marked locally. Not sent to OpenOLAT.')):''}`:`<div class="task-row"><strong>LMS-SYNC-01</strong>${badge(t('Musterfehler','Sample error'))}</div><p>${t('Kurszuordnung unklar. Wiederholung erst nach geklärter Zuordnung; keine doppelten Zugänge.','Course assignment unclear. Retry only after clarification; no duplicate access.')}</p>${vbtn(t('Fehlerpfad ansehen','View error path'),'workflow-open','WF-W09-02-02')}`)}</div>${notice(t('BBB und Cloud-Drive bleiben geplante Adapteransichten. Importierte Unterrichtszeiten sind keine bestätigte Anwesenheit.','BBB and cloud drive remain planned adapter views. Imported lesson times are not confirmed attendance.'))}`}
function fspView(r,testas=false){if(r.endsWith('/documents'))return `<div class="info-grid">${panel(t('Digitale Unterlagen','Digital documents'),['Abschlusszeugnis','Sprachnachweis','Antragsentwurf'].map((name,i)=>`<div class="file-row"><div><strong>${name}</strong><small>${V2.pageResults['fsp-doc-'+i]?t('Muster ergänzt · Prüfung offen','Sample added · review pending'):t('Noch offen','Pending')}</small></div>${vbtn(t('Muster ergänzen','Add sample'),'scenario','fsp-doc-'+i,'small secondary')}</div>`).join(''))}${panel(t('Physische Unterlagen','Physical documents'),`<p>${t('Ein digitaler Nachweis bestätigt nicht den Eingang erforderlicher Originale oder beglaubigter Fassungen. Der tatsächliche Eingang bleibt ein eigener Prüfschritt.','Digital evidence does not confirm receipt of required originals or certified copies. Actual receipt remains a separate check.')}</p><div class="task-row"><strong>${t('Muster-Eingang','Sample receipt')}</strong>${badge(t('Nicht bestätigt','Not confirmed'))}</div>${vbtn(t('Eingangsprüfweg ansehen','View receipt review'),'workflow-open','WF-W13-05-02')}`)}</div>`;return `<div class="info-grid">${panel(testas?t('Kohorte & Nachweise','Cohort & evidence'):t('Deine FSP-Akte · Muster','Your FSP record · sample'),`<p>${testas?t('Offizielle Anmeldung, Ergebnis und Sprachzertifikat werden getrennt nachgehalten. Ein Wechsel zum FSP-Weg benötigt eine Entscheidung.','Official registration, result and language certificate are tracked separately. Switching to the FSP pathway requires a decision.'):t('Interne und externe Kandidaten haben einen nachvollziehbaren Unterlagenweg. Die eigenständige Aufnahme-/Preislogik für Externe ist noch zu konkretisieren.','Internal and external candidates have a traceable document process. External admission and pricing logic still needs clarification.')}</p><div class="task-row"><strong>${testas?'TestAS-Ergebnis':t('Digitale Unterlagen','Digital documents')}</strong>${badge(t('Muster: Prüfung offen','Sample: review pending'))}</div><div class="task-row"><strong>${testas?t('Sprachzertifikat','Language certificate'):t('Physische Unterlagen','Physical documents')}</strong>${badge(t('Separater Nachweis','Separate evidence'))}</div>${vbtn(t('Musternachweis ergänzen','Add sample evidence'),'scenario',testas?'testas-evidence':'fsp-evidence','')}${V2.pageResults[testas?'testas-evidence':'fsp-evidence']?notice(t('Musternachweis ergänzt, nicht bestätigt. Menschliche Prüfung erforderlich.','Sample evidence added, not confirmed. Human review required.')):''}`)}${panel(testas?t('Intensivwoche & Wechsel','Intensive week & pathway change'):t('Freigabe & Versand','Approval & dispatch'),`<p>${testas?t('Kohorten und Stundenplan bleiben abgestimmt. Eine zusätzliche FSP-Workshopfreigabe ist ein eigener Vorgang.','Cohorts and timetables stay aligned. An additional FSP workshop approval is a separate process.'):t('Digitale Vollständigkeit ersetzt weder physische Vollständigkeit noch den tatsächlichen Versandbeleg. Behördliche Rückmeldung und Ergebnisbestätigung folgen später.','Digital completeness replaces neither physical completeness nor actual dispatch evidence. Authority response and result confirmation follow later.')}</p>${vbtn(t('Konkreten Workflow öffnen','Open specific workflow'),'workflow-open',testas?'WF-W13-11-05':r.endsWith('dispatch')?'WF-W13-06-02':'WF-W13-05-02')}`)}</div>`}
function managementView(r){return `<div class="filter-bar">${field(t('Bereich','Area'),'management.area',[['all',t('Alle Musterbereiche','All sample areas')],['education',t('Kurse','Courses')],['housing',t('Wohnen','Housing')],['exam',t('Prüfungen','Exams')]],'all')}${field(t('Periode','Period'),'management.period',[['demo','Musterperiode A'],['previous','Musterperiode B']],'demo')}<div style="align-self:end">${vbtn(t('Berichtsvorschau aktualisieren','Refresh report preview'),'scenario','management-report','','')}</div></div><div class="metric-grid">${[['12',t('Bestätigte Musterfälle','Confirmed sample cases')],['4',t('Offene Prüfungen · Muster','Pending reviews · sample')],['3',t('Bereichsmodelle','Area models')]].map(([n,l])=>`<div class="metric-card"><b>${n}</b><span>${l}</span></div>`).join('')}</div>${panel(t('Umsatz ist nicht Zahlungseingang.','Revenue is not cash received.'),`<p>${t('Diese Ansicht zeigt bewusst keine erfundenen echten Finanzzahlen. Umlageschlüssel, Berichtsversion und Datenbestätigung gehören zum jeweiligen Bericht.','This view intentionally shows no invented real financial figures. Allocation keys, report version and confirmed data belong to each report.')}</p>${workflowBrief(relevantProfile('management',r))}`)}`}
function workflowPage(id){const p=COVERAGE.profile_mapping.find(x=>x.id===id);if(!p)return notFound();const a=areaById(p.area_ids[0]);const f=V2.flows[id]||(V2.flows[id]={step:0,decisions:{},exception:null});return vheading(a,esc(p.title),t('Quellgebundene Ablaufvorschau. Schritte als gelesen markieren, Entscheidungen und Ausnahmen erkunden — keine Ausführung des Fachprozesses.','Source-bound workflow preview. Mark steps reviewed and explore decisions and exceptions — no execution of the business process.'))+subnav([['/coverage/'+a.id,t('Zur Bereichsabdeckung','Area coverage')],[a.proposed_routes.find(x=>x.startsWith('/')&&!x.includes(':'))||'/staff',t('Fachbereich öffnen','Open workspace')],['/conflicts',t('Konfliktregister','Conflict register')]])+`<div class="v2-content">${PENDING_VARIANTS.filter(v=>v.profile===p.id).map(v=>notice(v.id+' · '+v.label+': '+v.status+'. Kein aktiver Funktions- oder Vertragsumfang behauptet.')).join('')}<div class="flow-subtitle">${p.id} · ${p.source_refs.map(s=>`${s.source}${s.section}${s.pages?.length?' / S. '+s.pages.join(','):''}`).join(' · ')}</div>${p.id.startsWith('WF-X')?notice(t('Erweiterungs-/Altplanungsprofil. Ein Quellprozess ist keine Betriebsfreigabe. Aktuelle W-Regeln und das Konfliktregister haben Vorrang vor widersprechenden Automatikvorschlägen.','Extension / earlier planning profile. A source process is not operational approval. Current W rules and the conflict register take precedence over conflicting automation proposals.')):''}<div class="info-grid">${panel(t('Verantwortung','Responsibility'),p.roles.map(x=>`<p><b>${esc(x.role)}</b><br>${esc(x.responsibility)}<br><small>${esc(x.limit)}</small></p>`).join(''))}${panel(t('Nachweisstand','Evidence status'),`<div class="task-row"><strong>${t('Quelle','Source')}</strong>${badge(t('Spezifiziert','Specified'),'blue')}</div><div class="task-row"><strong>${t('Oberfläche','Interface')}</strong>${badge(t('Lokale Ablaufdemo','Local flow demo'),'blue')}</div><div class="task-row"><strong>${t('Fachabnahme / Integration','Business acceptance / integration')}</strong>${badge(t('Nicht nachgewiesen','Not evidenced'))}</div><p style="margin-top:14px">${esc(p.source_status)}</p>`)}</div><div class="content-topline" style="margin-top:28px"><h2>${t('Schritt für Schritt','Step by step')}</h2>${badge(`${Math.min(f.step,p.required_interactions.length)} / ${p.required_interactions.length} ${t('gelesen','reviewed')}`,'blue')}</div><div class="flow-steps">${p.required_interactions.map((s,i)=>`<div class="flow-step ${i<f.step?'done':i===f.step?'active':''}"><span class="step-index">${i+1}</span><div><strong>${esc(s.actor)}</strong><p>${esc(s.action)}</p>${i===f.step?vbtn(t('Als gelesen markieren','Mark reviewed'),'flow-next',p.id,'small secondary'):''}</div></div>`).join('')}</div>${p.source_supplement?`<details class="sub-page"><summary>${t('Vertiefter Quellennachtrag: Voraussetzungen, Daten, Schnittstellen und Grenzen','Detailed source supplement: prerequisites, data, interfaces and limits')}</summary><p><b>${t('Ziel','Goal')}:</b> ${esc(p.source_supplement.goal)}</p><p><b>Trigger:</b> ${esc(p.source_supplement.trigger)}</p>${['preconditions','inputs','data','interfaces','privacy','coverage_notes'].map(key=>`<h4>${key}</h4><ul>${p.source_supplement[key].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<p>${esc(p.source_supplement.result)}</p><small>SHA256 ${p.source_revision.sha256}</small></details>`:''}<h2>${t('Entscheidungen mit beiden Pfaden','Decisions with both paths')}</h2>${p.decisions.map((d,i)=>`<section class="decision-box"><span class="eyebrow">DEC-${i+1} · ${esc(d.owner||t('Zuständige Fachrolle','Authorised staff'))}</span><h4>${esc(d.condition)}</h4><div class="workflow-controls">${vbtn(t('Ja-Pfad ansehen','View yes path'),'flow-decision',p.id+'|'+i+'|yes','small secondary')}${vbtn(t('Nein-Pfad ansehen','View no path'),'flow-decision',p.id+'|'+i+'|no','small secondary')}</div>${f.decisions[i]?`<p><b>${f.decisions[i]==='yes'?t('Ja','Yes'):t('Nein','No')}:</b> ${esc(d[f.decisions[i]])}</p>`:''}</section>`).join('')}<h2 style="margin-top:30px">${t('Ausnahmen & Wiederaufnahme','Exceptions & recovery')}</h2>${p.exceptions.map((e,i)=>`<details class="sub-page"><summary>${esc(e.case)}</summary><p>${esc(e.handling)}</p><p><b>${t('Wiederaufnahme','Resume condition')}:</b> ${esc(e.resume_condition)}</p>${vbtn(t('Ausnahme im Demo-Verlauf markieren','Mark exception in demo history'),'flow-exception',p.id+'|'+i,'small secondary')}</details>`).join('')}${f.exception!==null?notice(t('Ausnahme erkundet. Kein automatischer Wiederanlauf oder Eingriff erfolgt.','Exception explored. No automatic restart or intervention occurred.')):''}<h2>${t('Testdefinitionen — nicht als bestanden behauptet','Test definitions — not claimed as passed')}</h2><p class="subtle">${t('Quelltexte bleiben im deutschen Original.','Source text is retained in its original German.')}</p>${p.acceptance_tests.map(test=>`<details class="sub-page"><summary>${test.id} · ${t('Geplanter Fachtest','Planned business test')}</summary><p><b>Given:</b> ${esc(test.given)}</p><p><b>When:</b> ${esc(test.when)}</p><p><b>Then:</b> ${esc(test.then)}</p>${badge(t('Produktivtest nicht ausgeführt','Production test not run'))}</details>`).join('')}<div class="module-aside"><h3>${t('Offene Punkte','Open questions')}</h3><ul>${p.open_points.map(s=>`<li>${esc(s)}</li>`).join('')||'<li>N/A</li>'}</ul></div><div class="flow-audit">${t('Lokaler Demonstrationsverlauf','Local demonstration history')}\n${V2.audit.filter(x=>x.id===p.id).map(x=>esc(x.message)).join('\n')||t('Noch keine Interaktion.','No interaction yet.')}</div><div class="actions">${vbtn(t('Lesefortschritt zurücksetzen','Reset review progress'),'flow-reset',p.id)}</div></div>`+sourceStrip(a.id)}
function coveragePage(id){const selected=id&&areaById(id)?id:V2.area;const list=COVERAGE.profile_mapping.filter(p=>(selected==='all'||p.area_ids.includes(selected))&&(!V2.filter||(p.title+' '+p.id+' '+p.source_refs.map(s=>s.source+s.section).join(' ')).toLowerCase().includes(V2.filter.toLowerCase())));return `<div class="v2-heading"><span class="eyebrow">${t('Quellen → Oberfläche → Interaktion → Test','Sources → interface → interaction → test')}</span><h1>${t('Nichts verschwinden lassen. Nichts vorschnell abhaken.','Leave nothing out. Mark nothing complete too soon.')}</h1><p>${t('291 Quellprofile, 34 Fachbereiche und 15 sichtbare Konflikte. Dieses Register trennt spezifizierte Anforderungen, klickbare Demonstration und noch fehlende Produktionsnachweise.','291 source profiles, 34 areas and 15 visible conflicts. This register separates specified requirements, clickable demonstrations and missing production evidence.')}</p></div>${subnav([['/coverage',t('Alle Profile','All profiles')],['/explore',t('Bereichsarchitektur','Area architecture')],['/conflicts',t('15 Quellkonflikte','15 source conflicts')],['/admin/acceptance',t('Abnahmeplanung','Acceptance planning')]])}<div class="v2-content"><div class="catalog-search"><input aria-label="${t('Quellprofile suchen','Search source profiles')}" id="coverage-search" value="${esc(V2.filter)}" placeholder="${t('Profil, Workflow-ID oder Quelle suchen …','Search profile, workflow ID or source …')}"><select id="coverage-area" aria-label="${t('Fachbereich','Area')}"><option value="all">${t('Alle Bereiche','All areas')}</option>${COVERAGE.areas.map(a=>`<option value="${a.id}" ${selected===a.id?'selected':''}>${a.title}</option>`).join('')}</select>${vbtn(t('Suchen','Search'),'coverage-search','','')}</div><div class="result-summary"><b>${list.length} ${t('Profile','profiles')}</b>${badge(t('Fachtests: Definitionen, keine Ausführung','Business tests: definitions, not execution'))}</div>${list.map(p=>`<article class="coverage-row"><div><strong>${esc(p.title)}</strong><small>${p.id} · ${p.source_refs.map(s=>s.source+s.section).join(' · ')}</small><p>${p.required_interactions.length} ${t('Schritte','steps')} · ${p.decisions.length} ${t('Entscheidungen','decisions')} · ${p.acceptance_tests.length} ${t('Testdefinitionen','test definitions')}</p><span class="phase">${t('Quellgebundene Ablaufdemo','Source-bound flow demo')}</span> <span class="status">${t('Integration / Fachabnahme offen','Integration / acceptance pending')}</span></div><div>${link(t('Ablauf erkunden','Explore flow'),'/workflow/'+p.id,'small secondary')}</div></article>`).join('')}</div>`}
function conflictsPage(){return `<div class="v2-heading"><span class="eyebrow">${t('Quellen nicht glattbügeln','Keep source differences visible')}</span><h1>${t('Unterschiede sichtbar entscheiden.','Resolve differences visibly.')}</h1><p>${t('Neuere Fachregeln, ältere Zielbilder und noch offene Freigaben bleiben getrennt. Kein Konflikt wird durch eine klickbare Oberfläche automatisch gelöst.','Newer business rules, earlier target models and outstanding approvals remain separate. A clickable interface does not automatically resolve conflicts.')}</p></div><div class="v2-content">${COVERAGE.conflicts.map(c=>`<section class="sub-page"><span class="phase conflict">${c.id}</span><h3 style="margin-top:12px">${esc(c.issue)}</h3><p>${esc(c.resolution)}</p><small>${esc(c.sources.join(' · '))}</small></section>`).join('')}<h2>${t('Geprüfter Quellennachtrag · Varianten nicht aktiviert','Reviewed source supplement · variants not activated')}</h2>${PENDING_VARIANTS.map(v=>`<section class="sub-page"><span class="phase planned">${v.id}</span><h3 style="margin-top:12px">${v.label}</h3><p>${v.status}</p><small>${v.profile||'Zuordnung in Prüfung'} · Unabhängiger Vier-Profil-Readback: PASS · 30.10.2026 · keine Betriebsfreigabe</small></section>`).join('')}<h2>${t('Fehlende Materialien','Missing materials')}</h2><ul>${COVERAGE.missing_materials.map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul></div>`}
function explore(staff=false,portalHub=false){const groups=staff?[['Fachbetrieb',['admission','propertyadmin','scheduling','teaching','fsp','testaspath','exam','university']],['Steuerung & Verwaltung',['finance','management','marketing','communication','chat','governance','hr']],['Erweiterungsbereiche',['nursing','employer','jobs','saas']]]:portalHub?[['Meine Bildungswege',['admission','portal','lms','selflearning','fsp','testaspath','exam','university','completion']],['Meine weiteren Bereiche',['tenant','arrival','contract','agency','jobs','employer','nursing']],['Fachrollen',['teaching','finance','propertyadmin','governance']]]:[['Lernen & Zukunft',['public','language','selflearning','nursinglanguage','exam','fsp','testaspath','university']],['Ankommen & Begleitung',['housing','tenant','arrival','services','shuttle','communication','publiccontent']],['Geplante Anschlusswege',['nursing','jobs','employer','saas']],['Portale & Fachbetrieb',['portal','admission','contract','lms','scheduling','teaching','completion','propertyadmin','agency','finance','management','marketing','chat','governance','hr']]];return `<div class="v2-heading"><span class="eyebrow">${t('Ein Ökosystem. Klare Zugänge.','One ecosystem. Clear access paths.')}</span><h1>${staff?t('Der richtige Arbeitsbereich für jede Aufgabe.','The right workspace for every task.'):portalHub?t('Dein Portal beginnt mit deinem Anliegen.','Your portal starts with your needs.'):t('Alles verbunden. Nichts versteckt.','Everything connected. Nothing hidden.')}</h1><p>${t('Bereiche, Rollen und Ausbauphasen sind ausdrücklich sichtbar. Dieser Wechsel ist eine Demo-Navigation — keine echte Anmeldung oder Berechtigungsprüfung.','Areas, roles and extension phases are explicitly visible. Switching is demo navigation — not real authentication or authorisation.')}</p></div>${subnav([['/explore',t('Alle Bereiche','All areas')],['/portal',t('Portale','Portals')],['/staff',t('Fachbereiche','Staff workspaces')],['/coverage',t('Quellen & Tests','Sources & tests')]])}<div class="v2-content">${groups.map(([title,ids])=>`<section style="margin-bottom:30px"><h2>${title}</h2><div class="module-grid">${ids.map(id=>{const a=areaById(id);let to=a.proposed_routes.find(r=>r.startsWith(staff?'/staff/':portalHub?'/portal/':'/')&&!r.includes(':'));if(!to)to=a.proposed_routes.find(r=>r.startsWith('/')&&!r.includes(':'))||'/coverage/'+id;return `<article class="module-card"><span class="index">${id.toUpperCase()}</span> ${phase(a)}<h3>${a.title}</h3><p>${esc(areaIntro(a.id))}</p><small>${a.roles.join(' · ')}</small><div class="actions">${link(t('Bereich öffnen','Open area'),to,'small secondary')}${link(t('Quellprofile','Source profiles'),'/coverage/'+id,'small ghost')}</div></article>`}).join('')}</div></section>`).join('')}</div>`}
const serviceCopy={visum:[t('Dein Visumweg bleibt nachvollziehbar.','Keep your visa pathway clear.'),t('Unterlagen, Antrag, Rückfragen und Bescheid gehören in einen klaren Verlauf. Die Entscheidung liegt bei der Behörde.','Documents, application, questions and the decision form a clear timeline. The authority makes the decision.'),['Unterlagen zusammenstellen','Status als Selbstauskunft erfassen','Bescheid bestätigen lassen'],'arrival'],ankunft:[t('Gut vorbereitet ankommen.','Arrive prepared.'),t('Reiseplanung, tatsächliche Ankunft und Einzug sind eigene Schritte. Besprich verspätete Einreise frühzeitig.','Travel plans, actual arrival and move-in are separate steps. Discuss late arrival early.'),['Ankunftsplanung festhalten','Unterkunft separat klären','Behördentermine vorbereiten'],'arrival'],sperrkonto:[t('Finanzierungsnachweis klären.','Clarify financial evidence.'),t('Ob und welcher Nachweis für deinen konkreten Weg erforderlich ist, muss mit den zuständigen Stellen geprüft werden. Keine Anbieter- oder Vertragsvermittlung im Pilot.','The evidence required for your pathway must be checked with the responsible bodies. No provider or contract mediation in this pilot.'),['Anforderungen bei zuständiger Stelle prüfen','Anbieterbedingungen vergleichen','Nachweis aufbewahren'],'services'],versicherung:[t('Versicherung bewusst auswählen.','Choose insurance deliberately.'),t('Leistungsumfang, Gültigkeit und Nachweisanforderungen gehören in eine persönliche Prüfung. Du behältst die Wahlfreiheit.','Coverage, validity and evidence requirements need individual review. You retain freedom of choice.'),['Benötigten Schutz klären','Leistungsbedingungen prüfen','Nachweis dem passenden Vorgang zuordnen'],'services'],bank:[t('Bankangelegenheiten vorbereiten.','Prepare banking arrangements.'),t('Vergleiche Bedingungen und notwendige Unterlagen selbst. Der Pilot eröffnet kein Konto und verarbeitet keine Bankdaten.','Compare conditions and required documents yourself. This pilot opens no account and processes no bank details.'),['Unterlagenbedarf prüfen','Gebühren und Bedingungen vergleichen','Eigene Entscheidung treffen'],'services'],mobilitaet:[t('Deinen Alltag in Aachen planen.','Plan everyday life in Aachen.'),t('Wege zwischen Unterkunft, Unterricht und Alltag zusammen betrachten. Keine aktuellen Tarife oder Fahrpläne im Pilot.','Consider journeys between housing, classes and daily life together. No current fares or timetables in this pilot.'),['Wohnlage und Kursort klären','Offizielle Verkehrsangebote prüfen','Persönlichen Ankunftsweg planen'],'services'],telekommunikation:[t('In Verbindung bleiben.','Stay connected.'),t('Laufzeit, Kosten und Kündigungsmöglichkeiten bewusst vergleichen. Keine SIM-Kartenbestellung oder Anbieterbindung.','Compare duration, costs and cancellation options. No SIM orders or provider commitment.'),['Nutzungsbedarf klären','Vertragsbedingungen vergleichen','Selbst Anbieter wählen'],'services'],transfer:[t('Ankunftstransfer · Ausbaukonzept','Arrival transfer · extension concept'),t('Flughafen- und Campus-Shuttle sind ältere Planungsbereiche, nicht als verfügbarer Betrieb bestätigt. Erkunde ausschließlich den disponierten Musterablauf.','Airport and campus shuttles are earlier planning areas, not confirmed operational services. Explore the sample dispatch flow only.'),['Ankunftsfenster angeben · Muster','Kapazität und Disposition prüfen','Bestätigung abwarten'],'shuttle']};
function servicesPage(r){const key=r.split('/').pop();const c=serviceCopy[key];const a=areaById(c?c[3]:'services');return vheading(a,c?c[0]:t('Gut begleitet in deinen Alltag.','Supported in everyday life.'),c?c[1]:t('Wohnen, Ankunft und praktische Fragen gehören zusammen. Du entscheidest, welche Hilfe du nutzen möchtest.','Housing, arrival and practical questions belong together. You decide which support to use.'))+subnav([['/services',t('Übersicht','Overview')],['/wohnen',t('Wohnen','Housing')],...Object.keys(serviceCopy).map(k=>['/services/'+k,routeName('/services/'+k)])])+`<div class="v2-content">${c?`<div class="info-grid">${panel(t('Deine Vorbereitung','Your preparation'),`<ul class="check-list">${c[2].map(x=>`<li>${x}</li>`).join('')}</ul>${vbtn(t('Checkliste im Demo-Guide vormerken','Save checklist in demo guide'),'scenario','guide-'+key,'')}${V2.pageResults['guide-'+key]?notice(t('In deinem lokalen Muster-Guide vorgemerkt. Keine Anfrage versendet.','Saved in your local sample guide. No enquiry sent.')):''}`)}${panel(t('Fragen persönlich klären','Clarify questions personally'),`<p>${t('Halte offene Fragen fest, bevor du etwas beauftragst. Verbindliche Anforderungen und Angebote müssen aktuell bestätigt werden.','Record open questions before commissioning anything. Binding requirements and offers need current confirmation.')}</p>${link(t('Beratung vorbereiten','Prepare guidance'),'/beratung','secondary')}${link(t('Welcome-Guide öffnen','Open welcome guide'),'/portal/welcome','secondary')}`)}</div>`:`<div class="module-grid"><a class="module-card" href="#/wohnen"><span class="index">STAY IN AACHEN</span><h3>${t('Zuerst dein Zuhause finden.','Find your home first.')}</h3><p>${t('Musterobjekte, Zimmer und eine unverbindliche Anfrage.','Sample properties, rooms and a non-binding enquiry.')}</p>${arrow}</a>${Object.entries(serviceCopy).map(([k,c])=>`<a class="module-card" href="#/services/${k}"><h3>${c[0]}</h3><p>${c[1]}</p>${arrow}</a>`).join('')}</div>`}</div>`+sourceStrip(a.id)}
function publicContent(r){const legal=['/rechtliches','/datenschutz','/agb','/widerruf','/preise'].includes(r);let content;if(legal)content=panel(routeName(r)+' · '+t('Freigabe erforderlich','Approval required'),`<p>${t('Diese Seite ist eine ausdrücklich nicht freigegebene Inhaltsposition im Konzept. Sie enthält keine erfundenen Rechtstexte, Preislisten oder verbindlichen Vertragsbedingungen.','This page is an explicitly unapproved content slot in the concept. It contains no invented legal text, price lists or binding contractual terms.')}</p><div class="task-row"><strong>${t('Verantwortliche Prüfung','Responsible review')}</strong>${badge(t('Offen','Pending'))}</div><div class="task-row"><strong>${t('Veröffentlichung','Publication')}</strong>${badge(t('Keine Produktivfreigabe','No production approval'))}</div>${vbtn(t('Datenschutz des Piloten lesen','Read pilot privacy'),'pilot-privacy')}`);else if(r.startsWith('/campus'))content=`<img class="campus-photo" src="assets/aachen-dom.jpg" alt="Aachener Dom — Motiv der bestehenden Website"><div class="info-grid" style="margin-top:23px">${panel(t('Aachen kennenlernen','Get to know Aachen'),`<p>${t('Ein neuer Lernort ist auch ein neuer Alltag. Wohnen, Ankunft und deine Fragen zur Umgebung lassen sich gemeinsam vorbereiten. Das Bild stammt von der bestehenden Website.','A new learning place also means a new everyday life. Housing, arrival and questions about the area can be prepared together. The image comes from the existing website.')}</p>${link(t('Wohnen entdecken','Explore housing'),'/wohnen','secondary')}`)}${panel(t('Dein erster Tag','Your first day'),`<ul class="check-list"><li>${t('Kursort und Start bestätigen','Confirm course location and start')}</li><li>${t('Anreise planen','Plan arrival')}</li><li>${t('Offene Fragen für die Beratung sammeln','Collect questions for guidance')}</li></ul>${link(t('Ankunftscheck','Arrival checklist'),'/services/ankunft','secondary')}`)}</div>`;else if(r==='/team')content=panel(t('Die passende Ansprechrolle finden.','Find the right contact role.'),`<p>${t('Im Pilot werden keine erfundenen Mitarbeitenden oder Zuständigkeiten einzelner Personen gezeigt. Wähle dein Thema, um den passenden Beratungsweg vorzubereiten.','The pilot shows no invented staff members or personal responsibilities. Choose your topic to prepare the right advisory pathway.')}</p><div class="pill-list">${[['Zulassung','/beratung'],['Sprachkurse','/sprachschule'],['Wohnen','/wohnen/anfrage'],['Prüfungen','/pruefungszentrum']].map(([l,to])=>`<a href="#${to}">${l}</a>`).join('')}</div>`);else if(r.startsWith('/wissen/')&&!r.includes('/laender/'))content=panel(t('Deine Unterlagen gut vorbereiten','Prepare your documents well'),`<p>${t('Eine geordnete Unterlagenmappe erleichtert die persönliche Prüfung. Zeugnis, Notenübersicht und vorhandene Sprachnachweise sollten unterscheidbar bleiben.','An organised document folder helps with personal review. Certificates, transcripts and language evidence should remain distinguishable.')}</p><ol><li>${t('Vorhandene Nachweise sammeln.','Collect existing evidence.')}</li><li>${t('Fehlende Angaben als offen markieren.','Mark missing information as pending.')}</li><li>${t('Individuelle Anforderungen bestätigen lassen.','Have individual requirements confirmed.')}</li></ol><p class="subtle">${t('Quelle: W3.3–3.5, Stand 22.10.2026. Keine individuelle Anerkennungsentscheidung.','Source: W3.3–3.5, 22 Oct 2026. Not an individual recognition decision.')}</p>${link(t('Bewerbung vorbereiten','Prepare application'),'/apply')}`);else if(r.includes('/laender/'))content=panel(t('Länder- und Abschlussinformation · Quellenprüfung offen','Country and qualification information · verification pending'),`<p>${t('Die geplante Länderansicht darf nur mit überprüften offiziellen Anerkennungsinformationen veröffentlicht werden. Dieser Pilot erfindet keine Abschlussbewertungen.','The planned country page must only be published with verified official recognition information. This pilot invents no qualification assessments.')}</p>${vbtn(t('Prüfprozess ansehen','View review process'),'workflow-open','WF-X074')}`);else content=`<div class="module-grid">${[['/wissen/unterlagen',t('Unterlagen vorbereiten','Prepare documents'),t('Was du vor deiner Beratung sortieren kannst.','What you can organise before guidance.')],['/faq',t('Häufige Fragen','Frequently asked questions'),t('Kurswahl, Bewerbung und nächste Schritte.','Programme choice, application and next steps.')],['/wissen/laender/demo',t('Abschluss & Herkunft','Qualification & origin'),t('Geplante Quellenansicht statt erfundener Anerkennung.','Planned source view instead of invented recognition.')],['/campus',t('Aachen kennenlernen','Explore Aachen'),t('Ankommen und deinen Alltag vorbereiten.','Arrive and prepare everyday life.')]].map(([to,title,desc])=>`<a class="module-card" href="#${to}"><h3>${title}</h3><p>${desc}</p>${arrow}</a>`).join('')}</div>`;return vheading(areaById('publiccontent'),legal?t('Verbindlichkeit braucht geprüfte Inhalte.','Binding information needs approved content.'):r==='/team'?t('Menschen für deinen nächsten Schritt.','People for your next step.'):r.startsWith('/campus')?t('Aachen wird Teil deiner Geschichte.','Aachen becomes part of your story.'):t('Wissen, das dich weiterbringt.','Knowledge that moves you forward.'),t('Orientierung aus dem beschriebenen Angebot, mit nachvollziehbaren Quellen und klaren Grenzen.','Orientation based on the described offering, with traceable sources and clear limits.'))+subnav([['/campus','Campus'],['/team','Team'],['/wissen',t('Wissen','Knowledge')],['/faq','FAQ'],['/rechtliches',t('Rechtliches','Legal')],['/preise',t('Preise','Prices')]])+`<div class="v2-content">${content}</div>`+sourceStrip('publiccontent')}
function communicationPage(r){const anon=r.includes('/beschwerde');const feedback=r==='/feedback';if(anon||feedback)return vheading(areaById('communication'),anon?t('Ein geschützter Weg für dein Anliegen.','A protected path for your concern.'):t('Deine Rückmeldung zählt.','Your feedback matters.'),anon?t('Die anonyme Demonstration ist vom Bewerberbrief getrennt. Bitte keine echten Namen oder sensiblen Angaben eingeben.','This anonymous demonstration is separate from the applicant brief. Do not enter real names or sensitive details.'):t('Kursfeedback als fiktiver, lokaler Ablauf. Keine Auswertung echter Personen.','Course feedback as a fictional local flow. No analysis of real people.'))+`<div class="v2-content">${panel(anon?t('Anonyme Muster-Meldung','Anonymous sample report'):t('Musterfeedback','Sample feedback'),`${field(t('Thema','Topic'),'communication.topic',[['teaching',t('Unterricht','Teaching')],['housing',t('Wohnen','Housing')],['support',t('Betreuung','Support')]],'support')}<label class="field">${t('Nur fiktiver Text','Fictional text only')}<textarea id="anonymous-text" maxlength="1000" placeholder="${t('Musteranliegen ohne persönliche Angaben …','Sample concern without personal details …')}"></textarea></label>${vbtn(t('Lokalen Ablauf simulieren','Simulate local flow'),'anonymous','','')}${V2.pageResults.anonymous?`<div class="demo-result">${t('Muster-Code: DEMO-ANON-01. Kein Versand, keine Speicherung und keine Verknüpfung mit Bewerberdaten.','Sample code: DEMO-ANON-01. No submission, storage or link to applicant data.')}</div>`:''}`)}</div>`+sourceStrip('communication');return vheading(areaById('communication'),t('Lass uns deine Fragen sortieren.','Let’s organise your questions.'),t('Wähle dein Anliegen. Der Pilot bereitet nur einen fiktiven Beratungsweg vor; er versendet keine Nachricht und bucht keinen Termin.','Choose your topic. This pilot only prepares a fictional guidance pathway; it sends no message and books no appointment.'))+subnav([['/beratung',t('Beratung','Guidance')],['/kontakt',t('Kontakt','Contact')],['/portal/appointments',t('Termine','Appointments')],['/feedback','Feedback'],['/beschwerde/anonym',t('Anonyme Meldung','Anonymous report')]])+`<div class="v2-content"><div class="module-grid">${[['/admission',t('Bewerbung & Bildungsweg','Application & education')],['/sprachschule/einstufung',t('Sprache & Einstieg','Language & entry')],['/wohnen/anfrage',t('Wohnen & Ankunft','Housing & arrival')],['/pruefungszentrum',t('Prüfung & Nachweis','Exams & evidence')]].map(([to,l])=>`<a class="module-card" href="#${to}"><h3>${l}</h3><p>${t('Deinen passenden nächsten Schritt vorbereiten.','Prepare your next step.')}</p>${arrow}</a>`).join('')}</div><div class="actions">${button(t('Beratungsbrief bearbeiten','Edit advisory brief'),'brief')}${button(t('Mustertermin auswählen','Choose sample appointment'),'appointment','secondary')}</div></div>`+sourceStrip('communication')}
function governanceView(r){const suffix=r.split('/').pop();if(suffix==='roles')return panel(t('Rollenmatrix · reine Vorschau','Role matrix · preview only'),`<div class="table-wrap"><table class="data-table"><thead><tr><th>${t('Rolle','Role')}</th><th>${t('Eigene / zugeordnete Akte','Own / assigned record')}</th><th>${t('Fremde Dokumente','Unrelated documents')}</th><th>${t('Rechte vergeben','Grant permissions')}</th></tr></thead><tbody>${[['Bewerber','Eigene','Nein','Nein'],['Lehrkraft','Zugeordnete Kurse','Nein','Nein'],['Agentur','Zugeordneter Status','Nein','Nein'],['Geschäftsführung','Nach Zuständigkeit','Nach Zuständigkeit','Gesonderte Freigabe']].map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div>${notice(t('Keine Rolle wird geändert. Dies ist keine technisch erzwungene ACL. Produktionsrechte und Delegationen benötigen eigene Prüfung.','No role is changed. This is not a technically enforced ACL. Production permissions and delegations require separate review.'))}${workflowBrief(relevantProfile('governance',r))}`);if(suffix==='integrations'||suffix==='sync-errors')return `<div class="module-grid">${[['OpenOLAT','Operativer Zieladapter'],['BBB / Drive','Geplanter Adapter'],['Finance / Bank','Nicht verbunden']].map(([name,status])=>`<div class="module-card"><span class="index">ADAPTER · DEMO</span><h3>${name}</h3><p>${status}</p>${badge(t('Keine Verbindung','Not connected'))}</div>`).join('')}</div>${panel(t('Fehlerqueue · EV-DEMO-01','Error queue · EV-DEMO-01'),`<p>${t('Musterfehler: Kurszuordnung fehlt. Idempotenzschlüssel DEMO-EV-01 bleibt bei Wiederholung gleich.','Sample error: course assignment missing. Idempotency key DEMO-EV-01 stays the same on retry.')}</p>${vbtn(t('Kontrollierten Retry simulieren','Simulate controlled retry'),'integration-retry','','')}${V2.pageResults.retry?notice(t('Ein lokaler Retry protokolliert; kein Netzwerkaufruf. Wiederholte Klicks erzeugen keinen zweiten Mustervorgang.','One local retry logged; no network call. Repeated clicks create no duplicate sample case.')):''}`)}`;if(suffix==='migration')return panel(t('Datenmapping vor Übernahme prüfen','Review mapping before import'),`${field(t('Quellfeld','Source field'),'migration.field',[['old_id','Legacy-ID → externe Referenz'],['email','Kontaktadresse → Prüfqueue']],'old_id')}${check(t('Dublettenkonflikt als Muster erkannt','Sample duplicate conflict detected'),'migration.duplicate',Boolean(V2.scenario.duplicate))}${vbtn(t('Importprüfung simulieren','Simulate import review'),'scenario','migration','')}${V2.pageResults.migration?notice(t('Musterimport bleibt in Prüfqueue. Keine Daten übernommen oder zusammengeführt.','Sample import remains in review queue. No data imported or merged.')):''}`);if(suffix==='acceptance')return panel(t('Abnahme ist mehr als ein grüner Button.','Acceptance is more than a green button.'),`<div class="task-row"><strong>${t('Quellprofile erfasst','Source profiles captured')}</strong>${badge('291 / 291','blue')}</div><div class="task-row"><strong>${t('Fachtests','Business tests')}</strong>${badge(t('Definiert, nicht produktiv ausgeführt','Defined, not run in production'))}</div><div class="task-row"><strong>${t('Schnittstellen / Rechte / Recovery','Integrations / permissions / recovery')}</strong>${badge(t('Offen','Pending'))}</div>${link(t('Nachweismatrix öffnen','Open evidence matrix'),'/coverage','secondary')}${workflowBrief(relevantProfile('governance',r))}`);return workflowBrief(relevantProfile('governance',r))}
function completionView(r){if(r==='/verify')return panel(t('Zertifikat prüfen · Democode','Verify certificate · demo code'),`<p>${t('Nur DEMO-CERT-01 wird als fiktiver gültiger Datensatz erkannt. Keine echte Zertifikatsprüfung oder öffentliche Personendaten.','Only DEMO-CERT-01 is recognised as a fictional valid record. No real certificate verification or public personal data.')}</p><label class="field">${t('Democode','Demo code')}<input id="verify-code" value="DEMO-CERT-01"></label>${vbtn(t('Muster prüfen','Check sample'),'verify','','')}${V2.pageResults.verify?notice(V2.pageResults.verify):''}`);if(r.includes('alumni'))return panel(t('In Verbindung bleiben — freiwillig.','Stay connected — voluntarily.'),`<p>${t('Alumni-Kontakt und Informationen zum weiteren Bildungsweg sind freiwillig. Keine automatische Übernahme in Karrierepools.','Alumni contact and information about the next educational step are voluntary. No automatic enrolment in career pools.')}</p>${check(t('Fiktives Alumni-Interesse vormerken','Note fictional alumni interest'),'alumni.optin',Boolean(V2.scenario.alumni))}${vbtn(t('Präferenz simulieren','Simulate preference'),'scenario','alumni','')}`);return workflowBrief(relevantProfile('completion',r))+panel(t('Zeugniskette','Certificate chain'),`<div class="task-row"><strong>${t('Geprüfte Kursdaten','Reviewed course data')}</strong>${badge(t('Muster','Sample'))}</div><div class="task-row"><strong>${t('Freigabe / Version','Approval / version')}</strong>${badge(t('Fachprüfung erforderlich','Review required'))}</div>${link(t('QR-Demoprüfung','QR demo verification'),'/verify','secondary')}`)}
function contractView(r){return `<div class="info-grid">${panel(t('Ein Angebot, ein nachvollziehbarer Vertrag.','One offer, one traceable contract.'),`<p>${t('Mustervertrag DEMO-C01 · Version 1. Zusätzliche Angebote werden derselben Personenakte zugeordnet, nicht einer Dublette.','Sample contract DEMO-C01 · version 1. Additional offers connect to the same person record, not a duplicate.')}</p>${field(t('Zahlende Stelle · Demo','Paying party · demo'),'contract.payer',[['self',t('Selbstzahler','Self-funded')],['third',t('Abweichender Zahler','Different payer')],['sponsor',t('Kostenträger','Funding body')]],'self')}${check(t('Minderjährigenfall im Muster markieren','Flag sample minor case'),'contract.minor',Boolean(V2.scenario.minor))}${vbtn(t('Vertragsprüfung simulieren','Simulate contract review'),'contract-check','','')}${V2.pageResults.contract?notice(V2.pageResults.contract):''}`)}${panel(t('Versionen und Zustimmung','Versions and consent'),`<div class="task-row"><strong>${t('Musterfassung','Sample version')}</strong>${badge('DEMO-V1','blue')}</div><div class="task-row"><strong>${t('Unterschrift','Signature')}</strong>${badge(t('Nicht vorhanden','Absent'))}</div><div class="task-row"><strong>${t('Zahlung / Zugang','Payment / access')}</strong>${badge(t('Separate Prüfung','Separate review'))}</div>${workflowBrief(relevantProfile('contract',r))}`)}</div>`}
function genericTaskBoard(a,r){const p=relevantProfile(a.id,r);if(!p)return `<div class="empty-state"><h3>${t('Spezifikation noch offen.','Specification pending.')}</h3><p>${esc(a.required_interaction)}</p>${link(t('Quellen ansehen','View sources'),'/coverage/'+a.id,'secondary')}</div>`;const role=p.roles[0]?.role||a.roles[0];return `<div class="content-topline"><h2>${routeName(r)}</h2>${badge(t('Fiktiver Fachvorgang','Fictional business case'),'blue')}</div>${workflowBrief(p)}<div class="workflow-lanes">${[[t('Vorbereiten','Prepare'),p.required_interactions[0]],[t('Prüfen','Review'),p.required_interactions[Math.min(1,p.required_interactions.length-1)]],[t('Entscheiden','Decide'),p.required_interactions[Math.min(2,p.required_interactions.length-1)]]].map(([title,s],i)=>`<section class="workflow-lane"><h3>${title}</h3><div class="record-card"><h4>DEMO-${a.id.toUpperCase()}-0${i+1}</h4><p>${esc(s.action)}</p><small>${esc(s.actor)}</small>${link(t('Schritt im Ablauf öffnen','Open flow step'),'/workflow/'+p.id,'small ghost')}</div></section>`).join('')}</div><div class="module-aside"><h3>${t('Entscheidungspunkt','Decision point')}</h3><p>${esc(p.decisions[0]?.condition||a.required_interaction)}</p><div class="actions">${vbtn(t('Ja-Pfad erkunden','Explore yes path'),'decision-preview',p.id+'|yes','small secondary')}${vbtn(t('Nein-Pfad erkunden','Explore no path'),'decision-preview',p.id+'|no','small secondary')}</div>${V2.pageResults[p.id]?notice(V2.pageResults[p.id]):''}</div>`}
function staffWorkspace(a,r){let content;if(a.id==='propertyadmin')content=propertyAdmin(r);else if(a.id==='finance')content=financeView(r);else if(a.id==='scheduling')content=scheduleView(r);else if(a.id==='lms')content=lmsView(r);else if(a.id==='fsp'||a.id==='testaspath')content=fspView(r,a.id==='testaspath');else if(a.id==='management')content=managementView(r);else if(a.id==='governance')content=governanceView(r);else if(a.id==='completion')content=completionView(r);else if(a.id==='contract')content=contractView(r);else if(a.id==='hr')content=notice(t('Quellkonflikt CF-07: Honorare und Lehrkräfteeinsatz gehören zum Kern. Zusätzliche persönliche Zeiterfassung, Payslips und Urlaubsverwaltung bleiben ältere, ungeklärte Planvarianten.','Source conflict CF-07: fees and teacher deployment are core. Additional personal time tracking, payslips and leave management remain earlier, unresolved planning variants.'))+genericTaskBoard(a,r);else if(a.id==='marketing')content=notice(t('Lead-Ausnahme: kein automatisches Nachfassen. Letzte und nächste manuelle Aktivität werden getrennt geführt.','Lead exception: no automatic follow-up. Last and next manual activities are tracked separately.'))+genericTaskBoard(a,r);else if(a.id==='agency')content=notice(t('Agentursicht: nur eigene zugeordnete Kandidaten, Status und Provision. Keine Bewerberdokumente oder internen Notizen.','Agency view: assigned candidates, status and commission only. No applicant documents or internal notes.'))+genericTaskBoard(a,r);else if(a.id==='chat')content=notice(t('Wissensantworten benötigen Quelle, Datum und fachliche Freigabe. Wissenslücken werden an Menschen übergeben; keine automatische Veröffentlichung.','Knowledge responses need source, date and professional approval. Gaps are handed to people; no automatic publication.'))+genericTaskBoard(a,r);else content=genericTaskBoard(a,r);return vheading(a,a.title,t('Rollenbezogene Arbeitsfläche mit konkreten Quellprozessen und lokalen Demonstrationen. Keine echten Akten oder produktiven Freigaben.','Role-based workspace with specific source workflows and local demonstrations. No real records or production approvals.'))+subnav(routeLinksFor(a))+`<div class="v2-content">${content}${relatedPanel(a.id)}</div>`+sourceStrip(a.id)}
function notFound(){return `<div class="v2-heading"><span class="eyebrow">404 · ${t('Nicht im Pilot','Not in pilot')}</span><h1>${t('Dieser Weg ist noch nicht definiert.','This path is not defined yet.')}</h1><p>${t('Keine generische Ersatzseite: Nutze die Bereichsübersicht oder das Quellenregister.','No generic substitute page: use the area overview or source register.')}</p>${link(t('Alle Bereiche','All areas'),'/explore')}</div>`}
const contextGuides={housing:[t('Wo möchtest du ankommen?','Where would you like to settle?'),t('Lage, Zimmerart, Zeitraum — wir ordnen deinen Wohnwunsch. Alle Objekte sind Muster.','Location, room type, dates — let’s organise your housing needs. Every property is a sample.'),[['Unterkunft eingrenzen','/wohnen/suche'],['Extern anfragen','/wohnen/extern'],['Mietablauf kennenlernen','/portal/tenant']]],tenant:[t('Dein Zuhause, Schritt für Schritt.','Your home, step by step.'),t('Einzug, Mangel, Verlängerung oder Auszug: Jeder Vorgang hat seinen eigenen Weg.','Move-in, issues, extension or move-out: each case has its own pathway.'),[['Einzug vorbereiten','/portal/tenant/handover'],['Mangel melden · Demo','/portal/tenant/issues'],['Verlängerung erkunden','/portal/tenant/extension']]],propertyadmin:[t('Belegung braucht Klarheit.','Occupancy needs clarity.'),t('Prüfe Bett, Zeitraum und Hauptmietende. Eine Empfehlung reserviert keinen Platz.','Review bed, period and head lease end. A suggestion reserves no place.'),[['Belegung prüfen','/staff/housing/occupancy'],['Warteliste ansehen','/staff/housing/waitlist'],['Hauptmietende prüfen','/staff/housing/headleases']]],language:[t('Welcher Einstieg passt zu dir?','Which starting point fits you?'),t('Lernziel und vorhandene Sprachkenntnisse helfen bei der Orientierung, nicht bei einer automatischen Einstufung.','Your goals and current language skills guide orientation, not automatic placement.'),[['Sprachstufen erkunden','/sprachschule'],['Einstufung ansehen','/sprachschule/einstufung'],['Selbstlernen kennenlernen','/sprachschule/selbstlernen']]],university:[t('Dein Studienwunsch wird konkret.','Make your study plans concrete.'),t('Merke Studiengänge, vergleiche Muster und bereite jede Bewerbung gesondert vor.','Save programmes, compare samples and prepare each application separately.'),[['Studiengang suchen','/hochschule/suche'],['Merkliste vergleichen','/hochschule/vergleich'],['Service verstehen','/hochschule/service']]],exam:[t('Prüfung und Vorbereitung trennen.','Separate exam and preparation.'),t('Modul, Kapazität und Zahlungsbestätigung gehören zusammen. Anbieterwege bleiben eigenständig.','Module, capacity and payment confirmation go together. Provider processes remain separate.'),[['ÖSD-Modul wählen','/pruefungszentrum/oesd/buchung'],['TestDaF-Anbieterweg','/pruefungszentrum/testdaf'],['Prüfungsstatus ansehen','/portal/exams']]],finance:[t('Beleg ist nicht Bankeingang.','A document is not bank receipt.'),t('Forderung, Zahlung, Zuordnung und Freigabe bleiben getrennte Zustände.','Claim, payment, matching and approval remain separate states.'),[['Zuordnung prüfen','/staff/finance/payments'],['Freigaben ansehen','/staff/finance/approvals'],['Ledger erkunden','/staff/finance/ledger']]],jobs:[t('Dein Profil bleibt deine Wahl.','Your profile remains your choice.'),t('Aktivierung, Match und Datenfreigabe sind getrennt und freiwillig.','Activation, matching and data sharing are separate and voluntary.'),[['Profil ansehen','/portal/candidate/profile'],['Matches erkunden','/portal/candidate/matches'],['Quellkonflikte prüfen','/conflicts']]],employer:[t('Passung vor Offenlegung.','Fit before disclosure.'),t('Anonyme Profile zuerst. Identität nur nach ausdrücklicher Kandidatenentscheidung.','Anonymous profiles first. Identity only after an explicit candidate decision.'),[['Talentpool ansehen','/portal/employer/talentpool'],['Matches ansehen','/portal/employer/matches'],['Interviewweg ansehen','/portal/employer/interviews']]]};
function contextArea(r){if(r.startsWith('/workflow/'))return areaById(COVERAGE.profile_mapping.find(p=>p.id===r.split('/').pop())?.area_ids[0]||'governance');if(r.startsWith('/coverage'))return areaById(r.split('/')[2]||'governance')||areaById('governance');return matchArea(r)||areaById(r==='/'?'public':r.startsWith('/portal/teacher')?'teaching':r.startsWith('/portal/admin')?'admission':r.startsWith('/portal/student')?'portal':r.startsWith('/portal/partner')?'agency':r.startsWith('/portal/applicant')?'admission':'public')}
function vAssistant(a){const r=route().split('?')[0];const workspace=/^\/(staff|admin|management|master|portal)/.test(r);const ctx=(r.startsWith('/beschwerde')?'anonymous':workspace?'role:'+a.id:'public:'+a.id);V2.context=ctx;const memory=V2.notes[ctx]||(V2.notes[ctx]={messages:[],brief:''});const guide=contextGuides[a.id]||[t('Ein klarer nächster Schritt.','A clear next step.'),t('Ich ordne die Inhalte dieses Bereichs anhand der hinterlegten Quellen. Fachliche Entscheidungen bleiben bei den zuständigen Menschen.','I organise this area’s content using the linked sources. Professional decisions remain with the responsible people.'),[[t('Bereich erkunden','Explore area'),a.proposed_routes.find(x=>x.startsWith('/')&&!x.includes(':'))||'/explore'],[t('Fachprozesse ansehen','View workflows'),'/coverage/'+a.id],[t('Offene Punkte verstehen','Review open questions'),'/conflicts']]];return `<aside class="assistant" id="context-companion" aria-label="${t('Kontextbezogene Assistenz','Contextual companion')}"><div class="assistant-head"><div class="assistant-symbol">${arrow}</div><div><b>${t('Dein Kontextbegleiter','Your context companion')}</b><small>${t('QUELLENBASIERT · REGELBASIERTE DEMO','SOURCE-BOUND · RULE-BASED DEMO')}</small></div></div><div class="assistant-body"><span class="eyebrow">${a.id==='housing'?'STAY IN AACHEN':esc(a.id.toUpperCase())}</span><h2>${guide[0]}</h2><p class="assistant-intro">${guide[1]}</p>${guide[2].map(([label,to])=>`<a class="suggestion" href="#${to}">${label}${arrow}</a>`).join('')}<p class="companion-context">${t('Kontext','Context')}: ${esc(a.title)}<br>${t('Quellen','Sources')}: ${esc(a.sources.join(' · '))}<br>${t('Stand: 22./30.10.2026 · keine Live-Daten','As of 22/30 Oct 2026 · no live data')}</p><div id="vchat-log" aria-live="polite">${memory.messages.map(m=>`<div class="chat-bubble ${m.role}"><small>${m.role==='user'?t('DU','YOU'):t('DEMO-BEGLEITER','DEMO COMPANION')}</small>${esc(m.text)}</div>`).join('')}</div><div class="brief-box"><b>${workspace?t('Arbeitsnotiz · nur dieser Bereich','Work note · this area only'):t('Dein Anliegen · nur dieser Bereich','Your request · this area only')}</b><p>${memory.brief?esc(memory.brief):t('Fragen und nächste Schritte sammeln. Keine echten persönlichen Angaben.','Collect questions and next steps. No real personal details.')}</p><button data-v2="context-brief">${t('Notiz bearbeiten','Edit note')} →</button></div></div><form class="assistant-compose" id="vchat-form"><label class="skip" for="vchat-input">${t('Frage zum aktuellen Bereich','Question about current area')}</label><textarea id="vchat-input" maxlength="500" placeholder="${t('Frage zu diesem Bereich — nur fiktive Angaben …','Question about this area — fictional details only …')}"></textarea><button class="btn" type="submit">${t('Nächsten Schritt klären','Clarify next step')}${arrow}</button><small>${t('Keine Live-KI. Keine Übermittlung. Sensible oder gesundheitsbezogene Daten gehören nicht in diese Demo. Rollen- und Bereichsnotizen bleiben getrennt.','Not live AI. No transmission. Sensitive or health data do not belong in this demo. Role and area notes stay separate.')}</small></form></aside>`}
function vRenderBody(r){if(r==='/')return home().replace('href="#/services/housing"','href="#/wohnen"')+`<section class="section"><span class="eyebrow">${t('Mehr Wege. Ein verbundenes System.','More pathways. One connected system.')}</span><h2>${t('Dein Bildungsweg hat viele Seiten.','Your learning journey has many sides.')}</h2><div class="pill-list">${[...publicDomains.slice(1),['/pflege',t('Pflege · Konzept','Nursing · concept')],['/karriere',t('Karriere · Konzept','Career · concept')],['/plattform',t('Schulplattform · Konzept','School platform · concept')],['/staff',t('Fachbereiche','Staff workspaces')]].map(([to,l])=>`<a href="#${to}">${l}</a>`).join('')}</div></section>`;if(r==='/explore')return explore();if(r==='/staff')return explore(true);if(r==='/portal')return explore(false,true);if(r==='/coverage'||r.startsWith('/coverage/'))return coveragePage(r.split('/')[2]);if(r==='/conflicts')return conflictsPage();if(r.startsWith('/workflow/'))return workflowPage(r.split('/').pop());if(r.startsWith('/wohnen')||r==='/services/housing')return housing(r==='/services/housing'?'/wohnen':r);if(r.startsWith('/portal/tenant'))return tenant(r);if(r.startsWith('/sprachschule')||r.startsWith('/lernen/')||r==='/pflege/fachsprache'||r==='/portal/learning/subscription')return languagePage(r);if(r.startsWith('/pruefungszentrum')||r==='/portal/exams')return exams(r);if(r.startsWith('/hochschule')||r.startsWith('/portal/university'))return university(r);if(r.startsWith('/pflege')||r.startsWith('/portal/nursing')||r==='/portal/supervisor')return nursing(r);if(r.startsWith('/karriere')||r.startsWith('/portal/candidate'))return careers(r);if(r.startsWith('/arbeitgeber')||r.startsWith('/portal/employer'))return careers(r,true);if(r.startsWith('/plattform')||r.startsWith('/standorte')||r.startsWith('/master'))return platform(r);if(r==='/services'||r.startsWith('/services/'))return servicesPage(r);if(['/kontakt','/beratung','/feedback'].includes(r)||r.startsWith('/beschwerde'))return communicationPage(r);if(r==='/faq'||r==='/help')return help();if(['/rechtliches','/datenschutz','/agb','/widerruf','/preise','/team','/wissen'].includes(r)||r.startsWith('/wissen/')||r.startsWith('/campus'))return publicContent(r);if(r.startsWith('/studienkolleg/fsp')||r==='/studienkolleg/testas')return publicExamPath(r);if(r==='/partner')return publicPartner();if(r==='/courses'||r==='/studienkolleg')return courseList()+subnav([['/studienkolleg/fsp','FSP'],['/studienkolleg/fsp/extern',t('Externe FSP','External FSP')],['/studienkolleg/testas','TestAS'],['/sprachschule',t('Sprachschule','Language school')]]);if(r.startsWith('/course/'))return courseDetail(r.split('/')[2]);if(r==='/admission')return admission();if(r==='/apply')return application();if(r==='/about')return about()+sourceStrip('governance');const ownAliases={'/portal/tasks':'tasks','/portal/documents':'documents','/portal/messages':'messages','/portal/appointments':'appointments','/portal/financials':'financials'};if(ownAliases[r])return portal('student',ownAliases[r])+subnav([['/portal',t('Alle Portalbereiche','All portal areas')]]);if(r.match(/^\/portal\/(applicant|student|teacher|admin|partner)(\/|$)/)){const a=matchArea(r);if(a&&['assessment','classbook','homework','candidates','commissions'].includes(r.split('/').pop()))return staffWorkspace(a,r);return portal(r.split('/')[2],r.split('/')[3]||'overview')+subnav([['/portal',t('Weitere Portalbereiche','More portal areas')],['/portal/learning',t('Lernräume','Learning rooms')],['/portal/contracts',t('Verträge','Contracts')],['/portal/tenant',t('Wohnen','Housing')],['/staff',t('Fachbetrieb','Staff workspaces')]])}const a=matchArea(r);if(a)return staffWorkspace(a,r);return notFound()}
const v1Render=render;render=function(){const status=document.getElementById('toast');if(status){status.textContent='';status.classList.remove('show');}clearTimeout(window.toastTimer);const r=route().split('?')[0];syncPersona(r);const a=contextArea(r);const body=vRenderBody(r);document.documentElement.lang=state.lang;const skip=document.querySelector('body > .skip');if(skip)skip.textContent=t('Zum Inhalt','Skip to content');document.getElementById('app').innerHTML=vHeader()+`<div class="layout"><main id="main" class="page" data-route="${esc(r)}" data-area="${a.id}">${body}${footer()}</main>${vAssistant(a)}</div>`;bind();vBind();V2.lastRoute=r;};
function setNested(path,value){const [group,key]=path.split('.');if(group==='housing')V2.housing.requested=false;if(group==='exam')V2.exam.booked=false;if(group==='university'&&key==='consent')V2.university.applied=false;if(group==='finance'&&key==='evidence'){V2.finance.matched=false;V2.finance.approved=false;}if(group==='candidate'&&key==='active')V2.candidate.accepted=false;if(V2[group]&&key in V2[group]){if(typeof V2[group][key]==='boolean')V2[group][key]=value===true||value==='true';else V2[group][key]=value;}else V2.scenario[key]=value;}
function vBind(root=document){root.querySelectorAll('[data-v2]').forEach(el=>el.addEventListener('click',()=>vAction(el.dataset.v2,el.dataset.value)));root.querySelectorAll('[data-vfield]').forEach(el=>el.addEventListener('change',()=>setNested(el.dataset.vfield,el.value)));root.querySelectorAll('[data-vcheck]').forEach(el=>el.addEventListener('change',()=>setNested(el.dataset.vcheck,el.checked)));root.querySelector('#ecosystem-select')?.addEventListener('change',e=>{if(e.target.value)location.hash=e.target.value});root.querySelector('#coverage-area')?.addEventListener('change',e=>{V2.area=e.target.value;location.hash='/coverage'+(V2.area==='all'?'':'/'+V2.area);if(route()==='/coverage')render()});root.querySelector('#coverage-search')?.addEventListener('keydown',e=>{if(e.key==='Enter')vAction('coverage-search')});root.querySelector('#vchat-form')?.addEventListener('submit',e=>{e.preventDefault();const val=document.getElementById('vchat-input').value.trim();if(!val)return;const a=contextArea(route().split('?')[0]);const memory=V2.notes[V2.context];memory.messages.push({role:'user',text:val});memory.messages.push({role:'assistant',text:t(`Für „${a.title}“ ist der nächste passende Schritt: ${a.required_interaction}. Das ist eine regelbasierte Orientierung aus ${a.sources.join(', ')} — keine individuelle Entscheidung. Nutze die Links oben oder die Fachprozesse, um konkrete Schritte und offene Fragen anzusehen.`,`For “${a.title}”, the next relevant step is: ${a.required_interaction}. This is rule-based orientation from ${a.sources.join(', ')} — not an individual decision. Use the links above or the source workflows to review specific steps and open questions.`)});memory.messages=memory.messages.slice(-6);render();document.getElementById('vchat-log')?.scrollIntoView({block:'nearest'})})}
function vModal(title,content,actions=''){modal(title,content,actions);vBind(document.getElementById('overlay'))}
function vAction(act,val=''){if(act==='jump-companion'){document.getElementById('context-companion')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(act==='filter-housing'||act==='filter-university')return render();if(act==='reset-housing'){V2.housing.location='all';V2.housing.type='all';V2.housing.equipment='all';V2.housing.period='semester';return render()}if(act==='housing-proof'){V2.housing.proof=true;return render()}if(act==='housing-request'){if(V2.housing.external&&!V2.housing.proof)return toast(t('Für den externen Weg zuerst einen Musternachweis ergänzen.','Add sample evidence before using the external pathway.'));V2.housing.requested=true;render();return toast(t('Musteranfrage vorbereitet. Keine Anfrage versendet und kein Zimmer reserviert.','Sample enquiry prepared. No enquiry sent and no room reserved.'))}if(act==='tenant-state'){V2.tenant[val]=true;return render()}if(act==='save-study'){V2.university.saved=V2.university.saved.includes(val)?V2.university.saved.filter(x=>x!==val):[...V2.university.saved,val];return render()}if(act==='university-apply'){if(!V2.university.consent)return toast(t('Die fiktive Einzelfreigabe fehlt noch.','Fictional individual approval is still missing.'));V2.university.applied=true;return render()}if(act==='exam-book'){if(Number(V2.exam.capacity)<1){V2.exam.booked=false;render();return toast(t('Kein Musterplatz frei. Keine Buchung möglich.','No sample place available. Booking is blocked.'))}if(!V2.exam.payment)return toast(t('Zahlungsbestätigung fehlt. Keine Platzfreigabe.','Payment confirmation is missing. No place approval.'));V2.exam.booked=true;return render()}if(act==='learning-activate'){V2.learning.active=true;return render()}if(act==='note-goal'){V2.pageResults.goal=val;return toast(t('Lernziel für Deutsch ','Learning goal for German ')+val+t(' lokal vorgemerkt.',' noted locally.'))}if(act==='assessment-path'){V2.scenario.assessment=V2.scenario.evidence==='test'?t('Schriftliche, freigegebene Testfassung → Auswertungsvorschlag → fachliche Entscheidung. Kein echter Test durchgeführt.','Approved written assessment → evaluation suggestion → professional decision. No real test performed.'):t('Zertifikat aufnehmen → Echtheit und Anerkennung prüfen → Niveau fachlich bestätigen. Keine automatische Anerkennung.','Collect certificate → review authenticity and recognition → confirm level professionally. No automatic recognition.');return render()}if(act==='workflow-open'){location.hash='/workflow/'+val;return}if(act==='scenario'){V2.pageResults[val]=true;render();return toast(t('Lokaler Musterstand aktualisiert — keine Fachaktion ausgeführt.','Local sample state updated — no business action executed.'))}if(act==='flow-next'){const p=COVERAGE.profile_mapping.find(x=>x.id===val);V2.flows[val].step=Math.min(p.required_interactions.length,V2.flows[val].step+1);V2.audit.push({id:val,message:'REVIEWED STEP '+V2.flows[val].step+' · no execution'});return render()}if(act==='flow-decision'){const [id,i,answer]=val.split('|');V2.flows[id].decisions[i]=answer;V2.audit.push({id,message:'EXPLORED DEC-'+(Number(i)+1)+' '+answer+' · no approval'});return render()}if(act==='flow-exception'){const [id,i]=val.split('|');V2.flows[id].exception=Number(i);V2.audit.push({id,message:'EXPLORED EXCEPTION '+(Number(i)+1)+' · no restart'});return render()}if(act==='flow-reset'){V2.flows[val]={step:0,decisions:{},exception:null};return render()}if(act==='coverage-search'){V2.filter=document.getElementById('coverage-search').value;return render()}if(act==='profile-exception'){const p=COVERAGE.profile_mapping.find(x=>x.id===val);return vModal(t('Ausnahme & Wiederaufnahme','Exception & recovery'),p.exceptions.map(e=>`<h3>${esc(e.case)}</h3><p>${esc(e.handling)}</p><p><b>${t('Wiederaufnahme','Resume')}:</b> ${esc(e.resume_condition)}</p>`).join(''))}if(act==='decision-preview'){const [id,answer]=val.split('|');const p=COVERAGE.profile_mapping.find(x=>x.id===id);V2.pageResults[id]=p.decisions[0]?.[answer]||t('Pfad noch zu klären.','Path still to clarify.');return render()}if(act==='occupancy-check'){const room=rooms.find(x=>x.id===val);return vModal(room.name+' · '+t('Belegungsprüfung','Occupancy check'),`<p>${room.status==='occupied'?t('Musterbett bereits belegt. Eine überlappende Reservierung wird nicht als zulässig dargestellt.','Sample bed is already occupied. An overlapping reservation is not shown as valid.'):t('Musterstatus anfragbar. Zeitraum und Hauptmietende müssen trotzdem geprüft werden. Keine Reservierung erfolgt.','Sample status allows enquiry. Dates and head lease end still need review. No reservation made.')}</p>`)}if(act==='property-gate'){const scenario=V2.scenario.scenario||'overlap';V2.pageResults.property=scenario==='clear'?t('Musterprüfung ohne Konflikt. Manuelle Freigabe erforderlich; keine Reservierung erfolgt.','Sample check has no conflict. Human approval required; no reservation made.'):scenario==='headlease'?t('Gesperrt: gewünschtes Mietende liegt nach Hauptmietende. Keine Reservierung.','Blocked: requested end is after head lease end. No reservation.'):t('Gesperrt: Belegungsüberschneidung am Bett. Keine Doppelbelegung.','Blocked: occupancy overlap at bed level. No double booking.');return render()}if(act==='finance-match'){if(!V2.finance.evidence)return toast(t('Nur ein Beleg reicht nicht: bestätigten Bankeingang simulieren.','A document alone is insufficient: simulate confirmed bank receipt.'));V2.finance.matched=true;return render()}if(act==='finance-approve'){if(!V2.finance.matched)return toast(t('Erst Zuordnungsvorschlag prüfen.','Review the matching suggestion first.'));V2.finance.approved=true;return render()}if(act==='schedule-check'){V2.pageResults.schedule=V2.scenario.room==='R-04'?t('Musterprüfung konfliktfrei. Änderung ab Datum müsste freigegeben und kommuniziert werden.','Sample check is conflict-free. Effective-date change would need approval and communication.'):t('Raumkonflikt erkannt: R-03 ist im Musterzeitfenster belegt. Keine Planänderung.','Room conflict detected: R-03 is occupied in the sample slot. No schedule change.');return render()}if(act==='schedule-change')return vModal(t('Änderung ab Wirksamkeitsdatum','Change from effective date'),`<p>${t('Lehrkraft- oder Raumwechsel betrifft nur die freigegebenen Termine ab Datum. Historische Unterrichtsdaten bleiben unverändert. Nutze die Konfliktprüfung in der Arbeitsfläche.','Teacher or room changes affect approved sessions from the effective date only. Historical teaching data remains unchanged. Use the conflict check in the workspace.')}</p>`);if(act==='integration-retry'){V2.pageResults.retry=true;return render()}if(act==='contract-check'){V2.pageResults.contract=V2.scenario.minor?t('Minderjährigenfall: erforderliche Zustimmung separat prüfen. Keine Signatur oder Vertragsbindung.','Minor case: review required consent separately. No signature or contractual commitment.'):t('Musterprüfung vorbereitet. Vertragsversion, Zahler und Einwilligungen bleiben separat.','Sample review prepared. Contract version, payer and consent remain separate.');return render()}if(act==='candidate-save')return toast(V2.candidate.active?t('Fiktive Aktivierung lokal vorgemerkt. Kein Poolzugang erstellt.','Fictional activation noted locally. No pool access created.'):t('Fiktives Profil bleibt inaktiv.','Fictional profile remains inactive.'));if(act==='match-accept'){if(!V2.candidate.active)return toast(t('Freiwillige Demo-Aktivierung fehlt.','Voluntary demo activation is missing.'));V2.candidate.accepted=true;return render()}if(act==='match-decline'){V2.candidate.accepted=false;render();return toast(t('Musteranfrage abgelehnt. Keine Datenfreigabe.','Sample request declined. No data shared.'))}if(act==='employer-match')return vModal(t('Matchanfrage · Demo','Match request · demo'),`<p>${val}: ${t('Anfrage vorbereitet. Identität bleibt verborgen, bis der Kandidat zustimmt. Keine Nachricht versendet.','Request prepared. Identity remains hidden until the candidate agrees. No message sent.')}</p>`,link(t('Kandidatensicht ansehen','View candidate side'),'/portal/candidate/matches','secondary')+button(t('Schließen','Close'),'close-modal','secondary'));if(act==='pool-filter')return toast(t('Anonymer Musterpool aktualisiert.','Anonymous sample pool refreshed.'));if(act==='interview'){if(!V2.candidate.accepted)return toast(t('Zuerst einen Muster-Match aus Kandidatensicht annehmen.','First accept a sample match from the candidate view.'));return toast(t('Interviewfenster lokal vorgemerkt. Keine Einladung versendet.','Interview slot noted locally. No invitation sent.'))}if(act==='verify'){V2.pageResults.verify=document.getElementById('verify-code').value.trim()==='DEMO-CERT-01'?t('Fiktiver Datensatz DEMO-CERT-01 · Muster-Version 1 · keine echte Urkunde.','Fictional record DEMO-CERT-01 · sample version 1 · not a real certificate.'):t('Kein Musterdatensatz zu diesem Code gefunden.','No sample record found for this code.');return render()}if(act==='anonymous'){if(!document.getElementById('anonymous-text').value.trim())return toast(t('Bitte einen fiktiven Text ergänzen.','Please add fictional text.'));V2.pageResults.anonymous=true;return render()}if(act==='pilot-privacy')return action('privacy');if(act==='context-brief'){const memory=V2.notes[V2.context];return vModal(t('Bereichsnotiz bearbeiten','Edit area note'),`<p>${t('Nur fiktive Angaben. Diese Notiz bleibt im aktuellen Bereich und wird nicht übertragen.','Fictional details only. This note stays in the current area and is not transmitted.')}</p><label class="field">${t('Deine Fragen','Your questions')}<textarea id="context-note" maxlength="1200">${esc(memory.brief)}</textarea></label>`,vbtn(t('Notiz übernehmen','Use note'),'context-save','',''))}if(act==='context-save'){V2.notes[V2.context].brief=document.getElementById('context-note').value;closeModal();return render()}}
