function areaIntro(id){const descriptions={public:'Finde die Studienvorbereitung, die zu deinem Ziel passt.',admission:'Bereite deinen Bildungsweg und die persönliche Beratung vor.',contract:'Behalte deine Angebote und Vertragsversionen im Blick.',language:'Entdecke Deutsch A1 bis C1 und deinen passenden Einstieg.',selflearning:'Lerne in deinem Tempo mit einem klaren Zeitfenster.',nursinglanguage:'Entdecke sprachliche Vorbereitung im Pflegekontext.',exam:'Finde deinen Prüfungsweg und den passenden nächsten Schritt.',fsp:'Bereite Unterlagen, Workshop und deinen FSP-Weg vor.',testaspath:'Verbinde Vorbereitung, Anmeldung und Nachweise.',housing:'Finde Musterunterkünfte nach Lage, Zimmerart und Zeitraum.',tenant:'Begleite deinen Wohnalltag vom Einzug bis zur Rückgabe.',propertyadmin:'Arbeitsbereich für Bestand, Belegung und Mietvorgänge.',arrival:'Plane deine Ankunft und behalte offene Fragen im Blick.',services:'Stelle deinen persönlichen Ankunfts- und Alltagsplan zusammen.',shuttle:'Erkunde das geplante Transferkonzept ohne echte Buchung.',university:'Suche, vergleiche und plane deine Studienwünsche.',portal:'Deine Angebote und nächsten Schritte an einem Ort.',lms:'Dein Lernraum, Materialien und offene Aufgaben.',scheduling:'Plane Kurse, Räume und Unterricht nachvollziehbar.',teaching:'Deine zugeordneten Kurse und Unterrichtsaufgaben.',completion:'Deine Abschlüsse, Bescheinigungen und nächsten Wege.',communication:'Finde den passenden Kontaktweg für dein Anliegen.',chat:'Redaktion und Qualität der bereitgestellten Wissensantworten.',marketing:'Arbeitsbereich für Interessenten, Kampagnen und Inhalte.',agency:'Begleite deine zugeordneten Kandidaten und Kooperationen.',finance:'Behalte Forderungen, Zuordnung und Prüfschritte getrennt im Blick.',management:'Bereichsübersicht für nachvollziehbare Entscheidungen.',nursing:'Erkunde geplante Ausbildungs-, Anerkennungs- und Praxiswege.',jobs:'Dein freiwilliger beruflicher Anschlussweg als Konzept.',employer:'Entdecke das geplante anonyme Matching mit Kandidatenfreigabe.',saas:'Erkunde Schulpartner, White-Label und Standortkonzepte.',publiccontent:'Lerne Aachen kennen und finde Antworten für deinen Einstieg.',governance:'Konzeptarbeitsplatz für Integration, Quellen und Abnahme.',hr:'Lehrkräfteeinsatz und Honorare; zusätzliche HR-Varianten in Klärung.'};return descriptions[id]||'Bereich erkunden.'}
function publicExamPath(r){const isTest=r.endsWith('testas');const a=areaById(isTest?'testaspath':'fsp');const external=r.endsWith('extern');return vheading(a,isTest?t('Dein TestAS-Weg beginnt mit einem Plan.','Your TestAS pathway starts with a plan.'):external?t('FSP-Vorbereitung auch von außen anfragen.','Explore the external FSP pathway.'):t('Gut vorbereitet zur Feststellungsprüfung.','Prepare for the assessment examination.'),isTest?t('Vorbereitung, offizieller Test und Sprachnachweis gehören zusammen — mit jeweils eigenen nächsten Schritten.','Preparation, the official test and language evidence belong together — each with its own next steps.'):t('Unterlagen sortieren, Fragen klären und deinen Prüfungsweg vorbereiten. Verbindliche Anforderungen werden individuell bestätigt.','Organise documents, clarify questions and prepare your exam pathway. Binding requirements are confirmed individually.'))+subnav([['/studienkolleg',t('Studienvorbereitung','University preparation')],['/studienkolleg/fsp','FSP'],['/studienkolleg/fsp/extern',t('Externer Weg','External pathway')],['/studienkolleg/testas','TestAS']])+`<div class="v2-content"><div class="info-grid">${panel(t('Deine Vorbereitung','Your preparation'),`<ul class="check-list"><li>${t('Deinen Bildungsweg und bisherige Nachweise klären','Clarify your education pathway and existing evidence')}</li><li>${t('Sprachstand und erforderliche Unterlagen besprechen','Discuss language level and required documents')}</li><li>${isTest?t('Offizielle Anmeldung und Vorbereitung getrennt planen','Plan official registration and preparation separately'):t('Digitale und benötigte physische Unterlagen vorbereiten','Prepare digital and any required physical documents')}</li></ul>${link(t('Beratung vorbereiten','Prepare guidance'),'/beratung')}`)}${panel(t('Dein Weg im Portal','Your pathway in the portal'),`<p>${external?t('Der externe FSP-Weg ist im beschriebenen Angebot vorgesehen. Die genaue Aufnahme- und Preislogik muss noch bestätigt werden. Eine Anfrage ist keine Registrierung zur Prüfung.','The external FSP pathway is included in the described offering. Detailed admission and pricing rules still need confirmation. An enquiry is not exam registration.'):t('Im Pilot kannst du sehen, wie Vorbereitung, Nachweise und Rückmeldungen an einem Ort zusammenkommen.','Explore how preparation, evidence and responses come together in the pilot.')}</p>${link(t('Portalvorschau öffnen','Open portal preview'),isTest?'/portal/testas':'/portal/fsp','secondary')}`)}</div></div>`+sourceStrip(a.id)}
function publicPartner(){return vheading(areaById('agency'),t('Gemeinsam Bildungswege begleiten.','Support learning pathways together.'),t('Der Partnerbereich verbindet zugeordnete Kandidaten, Status und Zusammenarbeit — mit klaren Grenzen für Dokumente und interne Informationen.','The partner area connects assigned candidates, status and collaboration — with clear limits for documents and internal information.'))+`<div class="v2-content"><div class="info-grid">${panel(t('Deine Kandidaten im Blick','Your candidates at a glance'),`<p>${t('Im Musterportal siehst du ausschließlich zugeordnete Status. Bewerberdokumente und interne Prüfnachrichten gehören nicht in die Agenturansicht.','The sample portal shows assigned statuses only. Applicant documents and internal review messages do not belong in the agency view.')}</p>${link(t('Partnerportal erkunden','Explore partner portal'),'/portal/partner')}`)}${panel(t('Zusammenarbeit klären','Clarify collaboration'),`<p>${t('Kooperation, Vertrag und Provision werden gesondert abgestimmt. Der Pilot nimmt keine echten Kandidaten auf.','Cooperation, contracts and commission are agreed separately. This pilot accepts no real candidates.')}</p>${link(t('Beratung vorbereiten','Prepare guidance'),'/beratung','secondary')}`)}</div></div>`+sourceStrip('agency')}
